node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
const source = await readFile('tgcloud/endpoints/getNote.js', 'utf8');
const { default: handler } = await import('data:text/javascript;base64,' + Buffer.from(source).toString('base64'));
assert.deepEqual(await handler({}, { initData: { user: { id: 123 } } }), { userId: 123 });
await assert.rejects(() => handler({}, {}), TypeError);
console.log('Local context logic passed; authentication untested.');
